P=[
pg(30, lesson(6,"Six","Sixth (6th)"), part("I","Sale Ads"),
 p("Sale ads are written to let you know about special prices or to make you believe you are getting a really good deal on a product. It is very important that you read all of the print in a sale ad. You need to know all the facts about a sale before you can make a wise choice."),
 p("On sale ads, large print and small print are often used. The large print gets your attention, and the small print usually gives you more specific information. For example, the large print may say **ONLY $ 6.98*, and the small print for that ad will say **monthly payment for six months*. Notice that in this case a star was used to let you know that there was more information. «Batteries not included» or «with a purchase of two or more» are other examples of what might be found in small print."),
 p("Ads do not always tell you everything you need to know in order to make a wise choice. For example, the ad may not tell you if the price applies only to certain color or sizes. Or it may not tell you how long the sale will last. When that happens, you need to find out these facts yourself. So my advice to you is read the ad carefully and thoroughly before going to the shop where the sale is offered."),
 img("l06-ads","330px")),
pg(31, h("Answer:"), wb("What are sale ads written for?","Why should we read all the print in a sale ad?","Do ads always tell you everything about a product?", rg="6px"),
 h("Look carefully at the following ad:"),
 {"t":"complete","items":["GOLD BRACELETS · ALL 18 k GOLD · UP TO 50% OFF"]},
 note("Prices regularly from $ 50 to $ 325 now only $ 35 to $ 250. — *Jewelry Paradise*, 556 Lincoln Road (Open daily 9 a.m. to 9 p.m.) Closed Sundays."),
 h("Questions on the ad."), wb("Are silver articles on sale?","What facts would you have to find out?","What is on sale?","Who would probably be interested in this kind of merchandise?", rg="6px")),
pg(32, img("l06-car","150px"), h("Advertise:"), inst("Write an ad offering this car for sale. Use the following expressions or/and others:"),
 {"t":"olist","num":False,"cols":3,"items":["Looks like","sport sedan","power steering","made of","light","smooth","engine","5 speed shift","power brakes","aerodynamic"]},
 lines(4)),
pg(32, part("II","Does Advertising Really Help Consumers?"),
 dlg("*Gary:* It’s really amazing how advertising on TV, on radio or magazines urges us to dress, live … in a certain way.","*Peter:* Yeah, and it’s not only amazing but also frightening, because all our ideas about how we’re supposed to behave and look come from advertising.","*Gary:* Just look at TV commercials. They tell us what sort or brand of shampoo, soap or perfume we should use.","*Peter:* And clothing…","*Gary:* Yes, and clothing too. They claim that unless we accept this … or … that style we won’t be successful in life.","*Peter:* Unfortunately, many people believe this, and that, of course, is not true.","*Gary:* I have a friend, Karen, you know her.","*Peter:* Isn’t she the girl who just graduated from college?","*Gary:* Yes, she got a degree in advertising. Well … She is very excited about her job, and when she has an idea that can be used to convince people to buy something, she won’t care about the quality of the product she’s trying to sell.","*Peter:* That’s typical in this sort of business, I guess.","*Gary:* Yeah, but that’s quite unfair to consumers.")),
pg(33, img("l06-media","220px"), inst("Write a paragraph in which you express your opinion about TV advertising in Venezuela. Discuss it with your teacher in a conversation group."), lines(6),
 part("III","Functions: Expressing opinions."),
 h("Formal"), dlg("– Personally, I think … (Chinese food is delicious)","– I think (It’s going to snow)","– I believe (Venezuelan economy will improve)","– In my opinion (Magallanes will win the championship).","– It seems to me (This is the best research paper)"),
 h("Informal"), dlg("– Margarita island is a paradise","– Isn’t this dress beautiful?","– The film was terrible, wasn’t it?")),
]
save("l06","Lesson Six",P,jobs)
